{"source": "def investigate(context, acquire):
    hist = acquire("history")

    def simulate(put_mode, trig, chan, actions):
        committed = {}
        tx = {"main": None, "other": None}
        snap = {"main": None, "other": None}
        changes_main = 0
        total_main = 0
        total_other = 0

        def apply_put(state, key, value):
            if put_mode == "ignore":
                if key in state:
                    return 0
                state[key] = value
                return 1
            if put_mode == "replace":
                state[key] = value
                return 1
            if key in state:
                if state[key] != value:
                    state[key] = value
                    return 1
                return 0
            state[key] = value
            return 1

        def apply_update(state, key, value):
            if key in state:
                if state[key] != value:
                    state[key] = value
                    return 1
                return 0
            return 0

        def apply_delete(state, key):
            if key in state:
                del state[key]
                return 1
            return 0

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                tx[conn] = {}
                snap[conn] = dict(committed)
            elif op == "commit":
                if tx[conn] is not None:
                    committed = dict(committed)
                    committed.update(tx[conn])
                    tx[conn] = None
                    snap[conn] = None
            elif op == "rollback":
                if tx[conn] is not None:
                    committed = snap[conn]
                    tx[conn] = None
                    snap[conn] = None
            else:
                if tx[conn] is not None:
                    state = tx[conn]
                else:
                    state = committed
                n = 0
                if op == "put":
                    n = apply_put(state, act["key"], act["value"])
                elif op == "update":
                    n = apply_update(state, act["key"], act["value"])
                elif op == "delete":
                    n = apply_delete(state, act["key"])
                if n:
                    if conn == "main":
                        changes_main = n
                        total_main += n
                    else:
                        total_other += n

        if chan == "changes":
            ch = changes_main
        elif chan == "total_changes":
            ch = total_main
        else:
            ch = total_main + total_other
        return ch, len(committed), sum(committed.values())

    candidates = []
    for put_mode in ("ignore", "replace", "upsert"):
        for trig in (False, True):
            for chan in ("changes", "total_changes", "total_changes_both"):
                candidates.append((put_mode, trig, chan))

    for r in hist:
        acts = r.get("actions", [])
        obs = r.get("observed", {})
        keep = []
        for c in candidates:
            ch, cc, cs = simulate(c[0], c[1], c[2], acts)
            if ch == obs.get("channel") and cc == obs.get("committed_count") and cs == obs.get("committed_sum"):
                keep.append(c)
        candidates = keep

    goal = context.get("goal")
    acts = context.get("actions", [])
    vals = set()
    for c in candidates:
        ch, cc, cs = simulate(c[0], c[1], c[2], acts)
        if goal == "channel":
            vals.add(ch)
        elif goal == "committed_count":
            vals.add(cc)
        elif goal == "committed_sum":
            vals.add(cs)
        else:
            return {"value": None, "unresolved": True}
    if len(vals) == 1:
        return {"value": list(vals)[0], "unresolved": False}
    return {"value": None, "unresolved": True}
", "scope": "Simulates the 18-member family (put mode x trigger x channel) and filters by calibration receipts; answers only when all surviving candidates agree.", "lesson": "The receipts pin put mode, trigger presence, and channel; simulating each candidate and intersecting predictions preserves uncertainty for underdetermined goals."}
